import { THEME_MODES } from "@rapid7/rds-theme-metadata-provider";
import { getOriginalTheme } from "./getOriginalTheme";
export const DarkOriginalTheme = getOriginalTheme(THEME_MODES.DARK);
export const LightOriginalTheme = getOriginalTheme(THEME_MODES.LIGHT);
/**
 * This object is deprecated and will be removed in a future release.
 *
 * Theme object containing light mode only. Use new <RDSThemeProvider> instead.
 * @deprecated
 */
export const RDSTheme = LightOriginalTheme;
/**
 * Theme map for the original RDS visual design, in both light & dark mode.
 */
export const OriginalThemeMap = {
    [THEME_MODES.DARK]: DarkOriginalTheme,
    [THEME_MODES.LIGHT]: LightOriginalTheme,
};
